SELECT gen_random_uuid(), c."Id", 'Bảo quản rau củ tươi lâu với ngăn rau của tủ lạnh', 'bao-quan-rau-cu-tuoi-lau', 'Đúng nhiệt độ, đúng độ ẩm và đúng cách đóng gói là ba yếu tố giúp rau củ giữ được độ giòn và màu tươi lâu hơn.', '/media/news/seed-bao-quan-rau-cu-tuoi-lau.jpg',
'<p>Rau củ mua về để vài hôm đã héo là chuyện quen thuộc. Thực ra chỉ cần sắp xếp lại một chút, ngăn rau của tủ lạnh có thể giữ rau tươi lâu hơn đáng kể.</p><h2>Để rau ở đúng ngăn</h2><p>Ngăn rau phía dưới có độ ẩm cao hơn các tầng khác, hợp cho rau lá và củ quả. Nhiều dòng tủ lạnh Bosch có ngăn VitaFresh cho phép điều chỉnh độ ẩm, giúp rau lá giữ được độ giòn.</p><h2>Sơ chế nhẹ trước khi cất</h2><ul><li>Nhặt bỏ lá úa, dập nát vì chúng làm phần còn lại hỏng nhanh hơn.</li><li>Không rửa rau trước khi cất; nếu đã rửa, để thật ráo nước.</li><li>Bọc rau lá trong khăn giấy rồi cho vào túi hoặc hộp có lỗ thoáng.</li></ul><h2>Tách riêng trái cây sinh khí ethylene</h2><p>Táo, chuối, bơ, cà chua tiết ra khí ethylene làm rau củ nhanh chín và héo. Hãy để chúng ở ngăn riêng hoặc trong hộp kín, cách xa rau lá.</p><h2>Giữ nhiệt độ ổn định</h2><p>Ngăn mát nên ở khoảng 3–5°C. Hạn chế mở cửa tủ lâu và không xếp đồ quá chật để khí lạnh lưu thông đều.</p>',
TRUE, TIMESTAMPTZ '2026-09-28T09:00:00+07:00', TIMESTAMPTZ '2026-09-28T09:00:00+07:00'
FROM (SELECT "Id" FROM "NewsCategories" WHERE "Id" = 'meo-hay-nha-bep' OR lower("Name") = lower('Mẹo hay nhà bếp') ORDER BY ("Id" = 'meo-hay-nha-bep') DESC LIMIT 1) c
WHERE NOT EXISTS (SELECT 1 FROM "NewsPosts" WHERE "Slug" = 'bao-quan-rau-cu-tuoi-lau' OR lower("Title") = lower('Bảo quản rau củ tươi lâu với ngăn rau của tủ lạnh'));

