SELECT gen_random_uuid(), c."Id", 'Chọn chương trình và nhiệt độ giặt phù hợp từng loại vải', 'chon-chuong-trinh-giat-phu-hop', 'Giặt đúng chương trình giúp quần áo sạch hơn, bền màu hơn và tiết kiệm điện nước. Đây là cách chọn nhanh cho các loại vải thường gặp.', '/media/news/seed-chon-chuong-trinh-giat-phu-hop.jpg',
'<p>Máy giặt hiện đại có rất nhiều chương trình, nhưng phần lớn gia đình chỉ dùng một hai chế độ quen thuộc. Chọn đúng chương trình cho từng loại vải giúp quần áo bền hơn và tiết kiệm điện nước.</p><h2>Đọc nhãn mác trước khi giặt</h2><p>Ký hiệu chậu nước trên nhãn cho biết nhiệt độ giặt tối đa. Nhãn có hình bàn tay nghĩa là chỉ nên giặt tay hoặc dùng chương trình giặt tay, đồ len của máy.</p><h2>Gợi ý theo loại vải</h2><ul><li><strong>Cotton:</strong> chương trình Cotton, 30–40°C cho đồ thường; 60°C cho khăn tắm, ga gối cần làm sạch kỹ.</li><li><strong>Vải tổng hợp, đồ thể thao:</strong> chương trình Synthetic hoặc Sportswear, nhiệt độ thấp, vắt nhẹ.</li><li><strong>Len, lụa:</strong> chương trình Wool hoặc Delicate, nước lạnh, vắt tốc độ thấp.</li><li><strong>Chăn, rèm:</strong> chương trình đồ cồng kềnh, không giặt quá tải.</li></ul><h2>Đừng giặt quá đầy</h2><p>Lồng giặt nên còn khoảng một gang tay phía trên để quần áo đảo đều. Với đồ dày như chăn, nên giặt ít hơn khối lượng tối đa của máy.</p><h2>Dùng lượng nước giặt vừa đủ</h2><p>Nhiều nước giặt không làm đồ sạch hơn mà còn để lại cặn trên vải và trong máy. Một số dòng máy giặt Bosch có tính năng định lượng tự động i-DOS, tự châm lượng nước giặt phù hợp với lượng đồ.</p>',
TRUE, TIMESTAMPTZ '2026-09-30T09:00:00+07:00', TIMESTAMPTZ '2026-09-30T09:00:00+07:00'
FROM (SELECT "Id" FROM "NewsCategories" WHERE "Id" = 'huong-dan-su-dung' OR lower("Name") = lower('Hướng dẫn sử dụng') ORDER BY ("Id" = 'huong-dan-su-dung') DESC LIMIT 1) c
