SELECT gen_random_uuid(), c."Id", 'Dùng bếp từ đúng cách: nồi chảo phù hợp và giữ mặt kính bền đẹp', 'dung-bep-tu-dung-cach', 'Bếp từ chỉ hoạt động với nồi có đáy nhiễm từ. Biết cách chọn nồi và vệ sinh mặt kính giúp bếp nấu nhanh và luôn sáng bóng.', '/media/news/seed-dung-bep-tu-dung-cach.jpg',
'<p>Bếp từ làm nóng trực tiếp đáy nồi nên nấu nhanh và an toàn hơn bếp gas. Để bếp phát huy hết hiệu quả, hãy lưu ý vài điều sau.</p><h2>Nồi chảo nào dùng được?</h2><p>Bếp từ chỉ nhận nồi có đáy nhiễm từ như inox 430, gang, thép tráng men. Cách thử nhanh: đưa nam châm lại gần đáy nồi, nếu hút chặt là dùng được.</p><ul><li>Chọn nồi đáy phẳng, đường kính gần bằng vùng nấu.</li><li>Nồi nhôm, thủy tinh, gốm thường không dùng được trừ khi có lớp đáy từ.</li></ul><h2>Nấu tiết kiệm điện</h2><ul><li>Đặt nồi đúng giữa vùng nấu.</li><li>Dùng mức công suất cao để đun sôi rồi hạ xuống để giữ sôi.</li><li>Đậy nắp khi nấu để giữ nhiệt.</li></ul><h2>Vệ sinh mặt kính</h2><p>Đợi mặt bếp nguội rồi lau bằng khăn mềm và dung dịch chuyên dụng cho mặt kính. Với vết bám cứng, dùng dao cạo chuyên dụng cho bếp kính, tránh miếng cọ kim loại làm xước bề mặt.</p><p>Không kéo lê nồi trên mặt kính và lau ngay khi thức ăn có đường bị trào để tránh để lại vết.</p>',
TRUE, TIMESTAMPTZ '2026-09-20T09:00:00+07:00', TIMESTAMPTZ '2026-09-20T09:00:00+07:00'
FROM (SELECT "Id" FROM "NewsCategories" WHERE "Id" = 'huong-dan-su-dung' OR lower("Name") = lower('Hướng dẫn sử dụng') ORDER BY ("Id" = 'huong-dan-su-dung') DESC LIMIT 1) c
WHERE NOT EXISTS (SELECT 1 FROM "NewsPosts" WHERE "Slug" = 'dung-bep-tu-dung-cach' OR lower("Title") = lower('Dùng bếp từ đúng cách: nồi chảo phù hợp và giữ mặt kính bền đẹp'));

INSERT INTO "NewsPosts" ("Id", "CategoryId", "Title", "Slug", "Summary", "CoverImageUrl", "Html", "IsPublished", "PublishedAt", "UpdatedAt")
SELECT gen_random_uuid(), c."Id", 'Pha cà phê ngon mỗi sáng với máy pha tự động', 'pha-ca-phe-ngon-moi-sang', 'Hạt cà phê, độ xay và cách đánh sữa quyết định phần lớn hương vị. Vài điều chỉnh nhỏ giúp ly cà phê đậm đà đúng gu.', '/media/news/seed-pha-ca-phe-ngon-moi-sang.jpg',
'<p>Máy pha cà phê tự động cho bạn ngay một ly espresso hay cappuccino chỉ với một nút bấm. Để ly cà phê ngon hơn, bạn có thể tinh chỉnh vài thiết lập.</p><h2>Chọn hạt và bảo quản đúng cách</h2><ul><li>Dùng hạt rang vừa hoặc rang đậm cho espresso; hạt mới rang trong vòng vài tuần cho hương thơm tốt nhất.</li><li>Đậy kín ngăn chứa hạt, tránh nắng và nơi nóng ẩm.</li></ul><h2>Điều chỉnh độ xay và độ đậm</h2><p>Xay mịn hơn cho vị đậm, xay thô hơn nếu cà phê bị đắng gắt. Thay đổi từng nấc nhỏ và thử qua vài ly để tìm mức phù hợp.</p><h2>Đánh sữa mịn cho cappuccino</h2><p>Dùng sữa tươi lạnh, sữa có độ béo cao cho lớp bọt dày và mịn. Vệ sinh vòi đánh sữa ngay sau mỗi lần dùng để sữa không đóng cặn.</p><h2>Bảo dưỡng định kỳ</h2><ul><li>Đổ bã và rửa khay hứng nước mỗi ngày.</li><li>Chạy chương trình tẩy cặn khi máy báo, nhất là ở nơi nước cứng.</li><li>Thay lõi lọc nước theo khuyến nghị của nhà sản xuất.</li></ul>',
TRUE, TIMESTAMPTZ '2026-09-22T09:00:00+07:00', TIMESTAMPTZ '2026-09-22T09:00:00+07:00'
FROM (SELECT "Id" FROM "NewsCategories" WHERE "Id" = 'mon-ngon-moi-ngay' OR lower("Name") = lower('Món ngon mỗi ngày') ORDER BY ("Id" = 'mon-ngon-moi-ngay') DESC LIMIT 1) c
WHERE NOT EXISTS (SELECT 1 FROM "NewsPosts" WHERE "Slug" = 'pha-ca-phe-ngon-moi-sang' OR lower("Title") = lower('Pha cà phê ngon mỗi sáng với máy pha tự động'));

INSERT INTO "NewsPosts" ("Id", "CategoryId", "Title", "Slug", "Summary", "CoverImageUrl", "Html", "IsPublished", "PublishedAt", "UpdatedAt")
SELECT gen_random_uuid(), c."Id", 'Dùng máy sấy bơm nhiệt sao cho tiết kiệm và giữ quần áo bền', 'dung-may-say-bom-nhiet-tiet-kiem', 'Máy sấy bơm nhiệt sấy ở nhiệt độ thấp nên êm với sợi vải. Vài thói quen nhỏ giúp máy sấy nhanh và tiết kiệm điện hơn.', '/media/news/seed-dung-may-say-bom-nhiet-tiet-kiem.jpg',
'<p>Máy sấy bơm nhiệt dùng không khí ấm ở nhiệt độ thấp hơn máy sấy thông thường, nhờ đó tiết kiệm điện và nhẹ nhàng hơn với quần áo. Để máy chạy hiệu quả, hãy lưu ý vài điều sau.</p><h2>Vắt kỹ trước khi sấy</h2><p>Chọn tốc độ vắt cao nhất mà loại vải cho phép. Quần áo càng ít nước, thời gian sấy càng ngắn.</p><h2>Phân loại đồ theo chất liệu</h2><ul><li>Sấy riêng đồ dày (khăn tắm, jeans) và đồ mỏng để đồ khô đều.</li><li>Kiểm tra nhãn mác, không sấy đồ có ký hiệu cấm sấy.</li></ul><h2>Vệ sinh bộ lọc sau mỗi lần sấy</h2><p>Bộ lọc xơ vải ở cửa máy cần được làm sạch sau mỗi mẻ. Bộ lọc bám xơ làm luồng khí yếu, máy sấy lâu và tốn điện hơn. Định kỳ vệ sinh cả bộ lọc ở dàn trao đổi nhiệt theo hướng dẫn của máy.</p><h2>Đổ nước ngưng</h2><p>Nếu máy không nối ống xả, hãy đổ bình chứa nước ngưng sau mỗi lần sấy để máy không phải dừng giữa chừng.</p>',
TRUE, TIMESTAMPTZ '2026-09-13T09:00:00+07:00', TIMESTAMPTZ '2026-09-13T09:00:00+07:00'
FROM (SELECT "Id" FROM "NewsCategories" WHERE "Id" = 'huong-dan-su-dung' OR lower("Name") = lower('Hướng dẫn sử dụng') ORDER BY ("Id" = 'huong-dan-su-dung') DESC LIMIT 1) c
WHERE NOT EXISTS (SELECT 1 FROM "NewsPosts" WHERE "Slug" = 'dung-may-say-bom-nhiet-tiet-kiem' OR lower("Title") = lower('Dùng máy sấy bơm nhiệt sao cho tiết kiệm và giữ quần áo bền'));

INSERT INTO "NewsPosts" ("Id", "CategoryId", "Title", "Slug", "Summary", "CoverImageUrl", "Html", "IsPublished", "PublishedAt", "UpdatedAt")
SELECT gen_random_uuid(), c."Id", 'Giữ máy hút mùi luôn sạch và hút mạnh', 've-sinh-may-hut-mui', 'Lưới lọc mỡ bám bẩn làm máy hút yếu và ồn hơn. Vệ sinh đúng cách giúp căn bếp luôn thoáng mùi.', '/media/news/seed-ve-sinh-may-hut-mui.jpg',
'<p>Máy hút mùi làm việc mỗi khi bạn nấu nướng, và lưới lọc mỡ là bộ phận gánh nhiều dầu mỡ nhất. Khi lưới bị bám bẩn, máy hút yếu hơn, ồn hơn và mùi thức ăn dễ lan khắp nhà.</p><h2>Vệ sinh lưới lọc mỡ</h2><p>Lưới lọc kim loại nên được vệ sinh khoảng 1–2 tháng một lần, thường xuyên hơn nếu gia đình hay chiên xào. Tháo lưới theo hướng dẫn của máy, ngâm nước ấm pha nước rửa chén rồi chải nhẹ. Nhiều loại lưới lọc kim loại có thể rửa bằng máy rửa bát.</p><h2>Thay lõi lọc than hoạt tính</h2><p>Với máy hút mùi chạy chế độ tuần hoàn (không có ống thoát ra ngoài), lõi than hoạt tính giữ lại mùi và không rửa được. Hãy thay lõi định kỳ theo khuyến nghị của nhà sản xuất.</p><h2>Thói quen khi nấu</h2><ul><li>Bật máy hút mùi vài phút trước khi bắt đầu nấu để tạo luồng hút ổn định.</li><li>Để máy chạy thêm 10–15 phút sau khi nấu xong để hút hết hơi nóng và mùi còn lại.</li><li>Dùng mức hút cao khi chiên rán, mức thấp khi hầm, luộc.</li></ul><h2>Lau thân máy</h2><p>Lau mặt kính và thân máy bằng khăn mềm, ẩm. Tránh dùng miếng cọ kim loại hoặc chất tẩy có tính mài mòn làm xước bề mặt.</p>',
TRUE, TIMESTAMPTZ '2026-09-26T09:00:00+07:00', TIMESTAMPTZ '2026-09-26T09:00:00+07:00'
FROM (SELECT "Id" FROM "NewsCategories" WHERE "Id" = 'meo-hay-nha-bep' OR lower("Name") = lower('Mẹo hay nhà bếp') ORDER BY ("Id" = 'meo-hay-nha-bep') DESC LIMIT 1) c
WHERE NOT EXISTS (SELECT 1 FROM "NewsPosts" WHERE "Slug" = 've-sinh-may-hut-mui' OR lower("Title") = lower('Giữ máy hút mùi luôn sạch và hút mạnh'));

INSERT INTO "NewsPosts" ("Id", "CategoryId", "Title", "Slug", "Summary", "CoverImageUrl", "Html", "IsPublished", "PublishedAt", "UpdatedAt")
SELECT gen_random_uuid(), c."Id", 'Hâm nóng và rã đông bằng lò vi sóng đúng cách', 'ham-nong-ra-dong-bang-lo-vi-song', 'Lò vi sóng giúp bữa ăn sẵn sàng chỉ trong vài phút. Vài mẹo nhỏ giúp thức ăn nóng đều, giữ được độ ẩm và hương vị.', '/media/news/seed-ham-nong-ra-dong-bang-lo-vi-song.jpg',
'<p>Lò vi sóng là trợ thủ quen thuộc cho những bữa ăn vội. Để thức ăn hâm nóng đều và rã đông không bị chín một phần, hãy thử vài mẹo dưới đây.</p><h2>Hâm nóng đều hơn</h2><ul><li>Dàn mỏng thức ăn trên đĩa, phần dày ra mép ngoài, phần mỏng vào giữa.</li><li>Đậy nắp chuyên dụng cho lò vi sóng để giữ hơi ẩm và tránh văng bẩn.</li><li>Hâm từng đợt ngắn, đảo đều giữa các lần để nhiệt lan khắp món ăn.</li><li>Để thức ăn nghỉ khoảng một phút sau khi hâm để nhiệt độ cân bằng.</li></ul><h2>Rã đông nhanh mà không chín mép</h2><p>Dùng chế độ rã đông theo khối lượng nếu lò có. Lật mặt thực phẩm giữa chừng và tách các miếng đã mềm ra trước. Nên chế biến ngay sau khi rã đông, không cấp đông lại.</p><h2>Dụng cụ dùng được trong lò vi sóng</h2><p>Dùng hộp thủy tinh, sứ hoặc nhựa có ký hiệu dùng được cho lò vi sóng. Không cho vật dụng kim loại, giấy bạc hoặc bát đĩa viền kim loại vào lò khi dùng chế độ vi sóng.</p><h2>Vệ sinh nhanh khoang lò</h2><p>Đặt một bát nước pha chút nước cốt chanh vào lò, chạy vài phút cho hơi nước làm mềm vết bẩn, rồi lau sạch bằng khăn ẩm.</p>',
TRUE, TIMESTAMPTZ '2026-09-18T09:00:00+07:00', TIMESTAMPTZ '2026-09-18T09:00:00+07:00'
FROM (SELECT "Id" FROM "NewsCategories" WHERE "Id" = 'mon-ngon-moi-ngay' OR lower("Name") = lower('Món ngon mỗi ngày') ORDER BY ("Id" = 'mon-ngon-moi-ngay') DESC LIMIT 1) c
WHERE NOT EXISTS (SELECT 1 FROM "NewsPosts" WHERE "Slug" = 'ham-nong-ra-dong-bang-lo-vi-song' OR lower("Title") = lower('Hâm nóng và rã đông bằng lò vi sóng đúng cách'));

INSERT INTO "NewsPosts" ("Id", "CategoryId", "Title", "Slug", "Summary", "CoverImageUrl", "Html", "IsPublished", "PublishedAt", "UpdatedAt")
SELECT gen_random_uuid(), c."Id", 'Lò nướng âm tủ: chọn dung tích và chức năng nào?', 'chon-lo-nuong-am-tu', 'Dung tích, chế độ nướng và cách vệ sinh là ba điểm nên so sánh khi chọn lò nướng âm tủ cho căn bếp gia đình.', '/media/news/seed-chon-lo-nuong-am-tu.jpg',
'<p>Lò nướng âm tủ giúp căn bếp gọn gàng và nướng được những mẻ lớn. Trước khi chọn, hãy cân nhắc vài yếu tố sau.</p><h2>Dung tích</h2><p>Phần lớn lò nướng âm tủ tiêu chuẩn có dung tích khoảng 65–71 lít, đủ cho gà nguyên con hay hai khay bánh cùng lúc. Gia đình ít người hoặc chủ yếu hâm nóng có thể cân nhắc lò kết hợp vi sóng nhỏ gọn hơn.</p><h2>Chế độ nướng nên có</h2><ul><li><strong>Quạt đối lưu:</strong> nướng nhiều tầng cùng lúc, nhiệt lan đều.</li><li><strong>Nướng trên dưới truyền thống:</strong> hợp cho bánh bông lan, bánh mì.</li><li><strong>Nướng vỉ (grill):</strong> làm vàng mặt món ăn, nướng thịt.</li><li><strong>Hâm nóng, rã đông, giữ ấm:</strong> tiện cho bữa ăn hằng ngày.</li></ul><h2>Cách vệ sinh</h2><p>Một số dòng lò có chức năng tự làm sạch hoặc lớp men dễ lau chùi, giúp tiết kiệm thời gian vệ sinh sau khi nướng.</p><h2>Kích thước lắp đặt</h2><p>Khoang tủ cho lò âm tiêu chuẩn thường rộng 60 cm, cao khoảng 60 cm. Lò có thể lắp dưới mặt bếp hoặc trong cột tủ cao ngang tầm mắt để thao tác thuận tiện hơn.</p>',
TRUE, TIMESTAMPTZ '2026-09-16T09:00:00+07:00', TIMESTAMPTZ '2026-09-16T09:00:00+07:00'
FROM (SELECT "Id" FROM "NewsCategories" WHERE "Id" = 'kinh-nghiem-chon-mua' OR lower("Name") = lower('Kinh nghiệm chọn mua') ORDER BY ("Id" = 'kinh-nghiem-chon-mua') DESC LIMIT 1) c
WHERE NOT EXISTS (SELECT 1 FROM "NewsPosts" WHERE "Slug" = 'chon-lo-nuong-am-tu' OR lower("Title") = lower('Lò nướng âm tủ: chọn dung tích và chức năng nào?'));
""");
        }

        protected override void Down(MigrationBuilder migrationBuilder)
        {
            migrationBuilder.Sql("""
DELETE FROM "NewsPosts" WHERE "Slug" IN ('tu-lanh-nhieu-cua-hay-side-by-side', 've-sinh-may-rua-bat-dinh-ky', 'bao-quan-rau-cu-tuoi-lau', 'chon-chuong-trinh-giat-phu-hop', 'meo-nuong-banh-quy-gion-deu', 'chon-khoi-luong-may-giat', 'dung-bep-tu-dung-cach', 'pha-ca-phe-ngon-moi-sang', 'dung-may-say-bom-nhiet-tiet-kiem', 've-sinh-may-hut-mui', 'ham-nong-ra-dong-bang-lo-vi-song', 'chon-lo-nuong-am-tu');
DELETE FROM "NewsCategories" c WHERE c."Id" IN ('huong-dan-su-dung', 'kinh-nghiem-chon-mua', 'mon-ngon-moi-ngay')
  AND NOT EXISTS (SELECT 1 FROM "NewsPosts" p WHERE p."CategoryId" = c."Id");
""");
        }
    }
}
